"""Build delivery prose from audited exports only; financial code unchanged."""
from pathlib import Path
import json
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results/2026-10-31-v1'
def main():
 m=pd.read_csv(OUT/'comparison_all.csv');refs=m[m.variant=='reference'];z=refs[refs.period=='ALL'].set_index('symbol')
 tests=json.loads((OUT/'TESTS.json').read_text(encoding='utf-8'));audit=json.loads((ROOT/'audit/AUDIT_RESULTS.json').read_text(encoding='utf-8'));extra=json.loads((ROOT/'audit/ADDITIONAL_CHECKS.json').read_text(encoding='utf-8'));screen=json.loads((OUT/'SCREENING.json').read_text(encoding='utf-8'));frozen=json.loads((OUT/'PRE_EXECUTION_PROTOCOL.json').read_text(encoding='utf-8'))
 result=' ; '.join(f"{s} {z.loc[s,'total_return_pct']:+.2f} % / {int(z.loc[s,'trades']):,} trades" for s in ('SPY','QQQ'))
 write=lambda p,s:(ROOT/p).write_text(s,encoding='utf-8',newline='\n')
 body='# Repli estimé sur les séances rouges — QQQ et SPY\n\n**Statut : '+screen['decision']+'** Références 2016–16/10/2026, après les mêmes frais : '+result+'.\n\n'
 body+='Niveau = ouverture − moyenne des max(Open−Close,0) des 21 séances précédentes, jours verts à zéro. Première clôture de 5 min sous le niveau de 09:35 à 15:30 New York ; entrée au marché une minute après décision. LONG, stop niveau−ADR 14, sortie open 15:59, pas de nuit. Taille entière, risque 1 % et cible 1× calculés avant le fill ; gap/frais peuvent dépasser ces cibles.\n\n'
 body+='Commission 0.0035 USD/action/côté min 0.35 USD ; friction adverse 0.01 USD/action/côté et stresses 0.02/0.03/0.05. Adaptation du signal public, pas réplication de ses ordres limites supposés remplis.\n\n'
 body+='[Rapport complet et quatre figures](results/2026-10-31-v1/RAPPORT_FINAL.md) · [84 comptes](results/2026-10-31-v1/comparison_all.csv) · [Protocole](PROTOCOL_EXECUTION.md) · [Recherche](RESEARCH.md) · [Interprétation](INTERPRETATION.md) · [Validation](VALIDATION.md).\n\n'
 body+='## Reproduction locale\n\nPython3.14 et versions requirements-lock.txt. Archives SIP et caches locaux vérifiés nécessaires, non redistribués ; aucun appel API ni clé requis par ces scripts. Pour recalculer, utiliser une copie séparée du checkout au même niveau, disposant des mêmes archives/préparations ignorées par Git. Cela protège les preuves originales. Depuis la racine de cette copie, avec dépendances installées :\n\n~~~powershell\n$env:PYTHONUTF8="1"\n$env:PYTHONDONTWRITEBYTECODE="1"\npython -m pytest studies/adaptive-red-day-dip/tests -q -p no:cacheprovider\npython studies/adaptive-red-day-dip/scripts/run_study.py --out studies/adaptive-red-day-dip/results/reproduction\n~~~\n\nLe runner refuse un dossier non vide. Dans cette copie seulement, fournir le même --out à audit/independent.py ; ce chemin doit rester SOUS studies/adaptive-red-day-dip. L’oracle écrit aussi audit/AUDIT_RESULTS.json à un emplacement fixe : ne pas le lancer sur une reproduction dans le checkout original, car il remplacerait la preuve archivée. Les scripts de statistiques et de présentation ciblent le run original par défaut ; adapter leurs chemins uniquement dans la copie pour une reproduction.\n\nVérification en lecture seule de la livraison originale :\n\n~~~powershell\n$env:PYTHONUTF8="1"\n$env:PYTHONDONTWRITEBYTECODE="1"\npython studies/adaptive-red-day-dip/scripts/verify_delivery.py --raw\n~~~\n\nEmpreintes = intégrité des octets, pas garantie de complétude ni de fills réels. A/B réutilisées, essais multiples et couverture conditionnelle. Aucun nouveau bot ; les deux simulations QQQ sont préservées.\n'
 write(Path('README.md'),body)
 lines=['# Interprétation','Référence après frais : '+result+'. Le test concerne notre adaptation confirmée/retardée, pas une certification ni une réfutation de chaque variante publique à ordre limite.']
 for s in ('SPY','QQQ'):
  rr=refs[refs.symbol==s].set_index('period');ci=json.loads((OUT/f'{s}_ALL_uncertainty.json').read_text(encoding='utf-8'))['blocks']['20']['conditional_daily_mean_ci95'];stress=m[(m.symbol==s)&(m.period=='A')&(m.variant=='cost_0.02')].iloc[0]
  failed=[k for k,v in screen['checks'][s].items() if not v]
  lines.append(f"{s} : A {rr.loc['A','total_return_pct']:+.2f} %, B {rr.loc['B','total_return_pct']:+.2f} %, ALL sans top3 {rr.loc['ALL','return_without_top3_days_pct']:+.2f} %, A friction doublée {stress.total_return_pct:+.2f} %. IC95 moyenne quotidienne ALL blocs20 : [{ci[0]*10000:.3f}, {ci[1]*10000:.3f}] bps. Critères échoués : {', '.join(failed) or 'aucun'}.")
  lines.append(f"{s} : PnL de mouvement de prix {rr.loc['ALL','price_move_pnl']:.2f} USD, friction {rr.loc['ALL','friction_cost']:.2f} USD et commission {rr.loc['ALL','commission']:.2f} USD, avec les quantités du compte net. Ce n’est pas un portefeuille gratuit recomposé.")
 lines+=['Toutes les 14 variantes et les trois périodes sont publiées. Une sensibilité gagnante isolée ne remplace pas les règles de référence choisies avant le PnL. Les mêmes archives ont servi à beaucoup de recherches ; B n’est plus une période aveugle et les IC ne corrigent pas la sélection multiple.',screen['decision']+' Aucun nouveau bot. Données conditionnelles à la couverture, pas de quotes ni de fills réels, source commune à l’oracle. SPY/QQQ corrélés, risques et expositions différents des deux bots existants ; aucun classement brut sur rendement seul.']
 write(Path('INTERPRETATION.md'),'\n\n'.join(lines)+'\n')
 cover=[]
 for s in ('SPY','QQQ'):
  d=pd.read_csv(OUT/f'{s}_ALL_reference/daily.csv');cover.append(s+' : '+', '.join(f'{k}={v}' for k,v in d.eligibility.value_counts().items()))
 validation=f"# Validation\n\n{tests['passed']} tests passent : estimations strictement passées, ADR 14 exact, jours verts zéro, compte rouge plafonné2, première candidate, géométrie, délai, taille, coûts, gap/stop/EOD, inconnus et parité scalaire synthétique.\n\nOracle : {audit['checks']} contrôles, {audit['executions']} comptes, {audit['feature_rows']} lignes de caractéristiques, {audit['trade_rows']} lignes de trades, {audit['daily_rows']} lignes quotidiennes recouvrantes. {extra['numeric_checks']} calculs agrégés et {extra['bootstrap_accounts']} comptes bootstrap blocs5/20 reproduits. Recouvrements entre variantes/périodes, pas autant d’observations indépendantes.\n\nGel avant premier PnL : {len(frozen['code_sha256'])} fichiers code/tests/runner/oracle/verifier, {len(frozen['dependencies_sha256'])} dépendances et2protocoles avec leur contenu. Présentation ajoutée après gel ; manifest final distinct. Prix bruts : les notes de dividendes héritées du profil source n’ajustent pas le corps ni l’ADR de ce test.\n\n"
 validation+='\n\n'.join(cover)+'\n\n'
 validation+='Revue pré-PnL dip_pre_review :42 tests vérifiés, aucun bloqueur financier ; P3 du filtre red2 corrigé avant calcul, puis 46 tests verts, dont régression et cas scalaires gap/inconnu. RED initial observé sur module absent ; corrections de fixtures OHLC et de frontière documentées dans le plan. Aucune règle modifiée après PnL.\n\n'
 validation+='Oracle sans import du moteur/statistiques, même source et chargeur ; cache par identité supposant les marchés immuables et maintenus en vie pendant main. Aucun deuxième fournisseur, carnet ou tick. complete_days sélectionne sur disponibilité future ; resolved_prefix révèle les inconnus actifs. Zéro de chaînage d’une exclusion n’est pas du cash observé.\n\n'
 validation+='[Tests](results/2026-10-31-v1/TESTS.json) · [Audit](audit/AUDIT_RESULTS.json) · [Agrégats](audit/ADDITIONAL_CHECKS.json) · [Gel](results/2026-10-31-v1/PRE_EXECUTION_PROTOCOL.json) · [Sources](WEB_SOURCE_STATUS.json). Quatre PNG vérifiés visuellement avant publication. Recalcul/audit dans une copie séparée avec données locales ; --out de l’oracle sous le dossier de l’étude, preuve d’audit fixe protégée. verify_delivery.py --raw est une vérification en lecture seule.\n'
 write(Path('VALIDATION.md'),validation)
 print(result)
if __name__=='__main__':main()
